"""Assemble the review atlas; never alters or generates the concept drawings."""
import json, html, pathlib, collections, zipfile
root = pathlib.Path(__file__).resolve().parents[1]
out = root / 'art/architecture-isometrique-proposition'
data = json.loads((out/'inventaire.json').read_text())
entries = [e for s in data['sheets'] for e in s['entries']]
assert len(entries) == len({e['id'] for e in entries}) == 234
catalog = json.loads((root/'data/architecture/catalogue.json').read_text())['assets']
assert set(catalog) == {e['id'] for e in entries}
esc = html.escape
cards=[]
for s in data['sheets']:
    number=s['number']; image=f'planche-{number:02}.png'
    assert (out/image).is_file(), image
    rows=''.join(f'<tr><td>{esc(e["id"])}</td><td>{esc(e["label"])}</td><td>{esc(e["family"])}</td><td>{e["width"]} × {e["depth"]} × {e["height"]}</td></tr>' for e in s['entries'])
    search=' '.join(str(e) for e in s['entries'])
    cards.append(f'<article data-search="{esc(search.lower(),quote=True)}"><h2>{number:02} · {esc(s["title"])}</h2><a href="{image}" target="_blank"><img loading="lazy" src="{image}" alt="Proposition isométrique {number}, {len(s["entries"])} références" width="1536" height="1024"></a><p><a href="{image}" download>Télécharger la planche PNG</a> · {len(s["entries"])} références attendues</p><details><summary>Identifiants et dimensions cibles</summary><table><thead><tr><th>ID</th><th>Fonction</th><th>Famille</th><th>L × P × H natives</th></tr></thead><tbody>{rows}</tbody></table></details></article>')
page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Hearthreaver · Proposition isométrique complète</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#0d211b;color:#eee4ce}body{max-width:1500px;margin:auto;padding:32px}header{max-width:1050px}h1{font-family:Georgia,serif;font-size:clamp(30px,5vw,58px);font-weight:normal}h2{font-size:20px;color:#ecd0a0}p,li{line-height:1.65}a{color:#e9b875}article{border-top:1px solid #ac7955;padding:25px 0 40px}img{display:block;width:100%;height:auto}input{box-sizing:border-box;width:100%;padding:16px;margin:20px 0;border:1px solid #ac7955;background:#142f26;color:white;font-size:16px}summary{cursor:pointer;padding:12px 0}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #345044}code{color:#edc087}.note{padding:18px;background:#213b30;border-left:3px solid #ce9863}[hidden]{display:none}nav{display:flex;gap:20px;flex-wrap:wrap}.stats{color:#e1ad7b;font-size:20px}footer{padding:30px 0;color:#c3bba7}</style>
<header><p>HEARTHREAVER · DIRECTION ARTISTIQUE · 20 OCTOBRE 2026</p><h1>Toute l’architecture,<br>en isométrie trois quarts.</h1><p class="stats">106 bâtiments · 8 variantes d’hiver · 120 modules · 12 nouvelles planches</p><p>Proposition issue de l’analyse du dépôt <a href="https://github.com/garwiglino/conan">garwiglino/conan</a>, état local <code>663f55f</code>. Chaque référence du catalogue est affectée à une planche ; la liste sous chaque image fait foi pour les identifiants et les dimensions.</p><nav><a href="architecture-isometrique-proposition.zip" download>Pack complet ZIP</a><a href="inventaire.json">Inventaire des 234 références</a><a href="../architecture-concepts-34/index.html">Anciennes propositions</a></nav>
<details open><summary>Analyse et corrections proposées</summary><ul><li><strong>Caméra :</strong> le précédent renderer applique <code>x = X + 0,5Y ; y = −0,5Y − Z</code>, ce qui conserve une façade horizontale. La cible de ce lot est une projection 2:1 symétrique : <code>x = X − Y ; y = (X + Y)/2 − Z</code>, sans point de fuite. Une même caméra doit servir aux maisons, murs, escaliers et passerelles.</li><li><strong>Échelle :</strong> conserver l’humain natif de 19 px, la tuile de 16 unités et le dégagement de porte de 22 px du catalogue. Le document de concepts mentionne aussi 24 px : cet écart doit être résolu lors de la fabrication. Largeur et profondeur sont des unités au sol ; hauteur et emprise projetée restent distinctes.</li><li><strong>Identités :</strong> conserver Teremor, Sylverive, Igea, Sarak, Varan et Tagon, leurs fonctions et leurs matériaux. Les bâtiments communs restent communs. Pas de drapeaux ni de bannières.</li><li><strong>Construction :</strong> les 120 pièces doivent conserver des extrémités raccordables, des angles et jonctions distincts, un niveau de passage commun et des escaliers accessibles. Les murs hauts régionaux visent 64 px de haut, avec circulation à 52 px.</li><li><strong>Lisibilité :</strong> entrées visibles, petites pièces réellement petites, toiture distincte des collisions, masses reconnaissables à taille de jeu. Le personnage de comparaison sert à détecter les écarts visuels.</li></ul></details>
<p class="note"><strong>Statut : proposition artistique.</strong> Les dessins générés indiquent des dimensions cibles ; leurs silhouettes, leurs personnages de comparaison et leurs raccords ne constituent pas une mesure native garantie. Les étiquettes peuvent comporter des erreurs de génération : consulter l’inventaire textuel. Un contrôle pixel par pixel et les quatre orientations restent nécessaires pour fabriquer les sprites de production. Ce lot propose une vue par référence ; il ne remplace pas les 696 vues techniques. Les versions été/hiver présentent encore des écarts de toiture et d’ouvertures : elles devront être recalées sur un même volume. Certaines jonctions en T ressemblent à des croisements et les modules de toiture sont parfois montrés avec des supports illustratifs : leurs raccords et leurs limites de découpe restent à reprendre. Certaines couleurs ou couvertures sont des alternatives artistiques à comparer aux originaux. Aucune intégration au moteur n’est effectuée.</p>
</header><label for="search">Rechercher un bâtiment, une région ou un identifiant</label><input id="search" type="search" placeholder="Ex. Sarak, T01, escalier, moulin…"><p id="count" role="status"></p><main>'''+''.join(cards)+'''</main><footer>Sources : data/architecture/catalogue.json ; sprites/architecture/human-reference.js ; sprites/architecture/architecture-34.js ; docs/architecture-trois-quarts.md ; docs/humains-architecture-concepts.md ; les 45 planches originales et leur manifeste. Inventaire complet vérifié par le script de construction de cette galerie ; conformité graphique à valider visuellement.</footer><script>const input=document.querySelector('#search'),cards=[...document.querySelectorAll('article')];function filter(){const q=input.value.toLocaleLowerCase('fr').trim();for(const card of cards)card.hidden=!card.dataset.search.includes(q);document.querySelector('#count').textContent=cards.filter(c=>!c.hidden).length+' / 12 planches affichées'}input.addEventListener('input',filter);filter();</script></html>'''
(out/'index.html').write_text(page)
with zipfile.ZipFile(out/'architecture-isometrique-proposition.zip','w',zipfile.ZIP_DEFLATED) as archive:
    for name in ['index.html','inventaire.json','provenance.json']+[f'planche-{s["number"]:02}.png' for s in data['sheets']]:
        archive.write(out/name,name)
print('234 références uniques, 12 PNG présents ; galerie et ZIP construits.')
